import { ViewEncapsulation, ChangeDetectionStrategy, Component, input } from '@angular/core';
@Component({
  selector: 'aevko-navigation-menu',
  standalone: true,
  template: '<ng-content />',
  styleUrl: './navigation-menu.component.css',
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { role: 'navigation', 'data-slot': 'navigation-menu', '[attr.aria-label]': 'label()' },
})
export class AevkoNavigationMenu {
  readonly label = input.required<string>();
}

:where(aevko-navigation-menu) {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem;
}
:where(aevko-navigation-menu) a,
:where(aevko-navigation-menu) button {
  align-items: center;
  background: transparent;
  border: 0;
  border-radius: 0;
  color: inherit;
  display: inline-flex;
  min-block-size: 2.5rem;
  padding: 0.5rem 0.75rem;
  text-decoration: none;
}
:where(aevko-navigation-menu) a:hover,
:where(aevko-navigation-menu) button:hover {
  background: var(--aevko-surface, #f4f4f5);
}
:where(aevko-navigation-menu) a:focus-visible,
:where(aevko-navigation-menu) button:focus-visible {
  outline: 2px solid var(--aevko-ring, #a3a3a3);
  outline-offset: 2px;
}
